-- Demo data: Half Yearly 2026 marks for 6B, board exam results, and the processed
-- results of the published Half Yearly exam (generated with src/lib/grading.ts by
-- scripts/seed-results.ts; regenerate it if the marks above change).

-- 6B: Fahim (roll 3) was absent for English; Lamia (roll 4) failed the MCQ part of
-- Science though her total is above 33.
insert into public.marks (exam_subject_id, student_id, cq, mcq, practical, is_absent, entered_by)
select es.id, en.student_id,
  case when en.roll = 3 and s.code = 'ENG' then null
       when en.roll = 4 and s.code = 'SCI' then 40
       else least(es.cq_full, round(es.cq_full * (0.50 + ((en.roll * 11 + s.sort_order * 5) % 45) / 100.0)))
  end,
  case when en.roll = 3 and s.code = 'ENG' then null
       when en.roll = 4 and s.code = 'SCI' then 6
       else least(es.mcq_full, round(es.mcq_full * (0.55 + ((en.roll * 3 + s.sort_order * 7) % 40) / 100.0)))
  end,
  case when en.roll = 3 and s.code = 'ENG' then null
       when es.practical_full > 0 then es.practical_full - (en.roll % 4)
  end,
  en.roll = 3 and s.code = 'ENG',
  '00000000-0000-4000-a000-000000000003'
from public.exams e
join public.exam_subjects es on es.exam_id = e.id
join public.subjects s on s.id = es.subject_id
join public.sections sec on sec.class_id = es.class_id and sec.name_en = 'B'
join public.enrollments en on en.section_id = sec.id and en.session_id = e.session_id
where e.status = 'published';

-- Board exam results (WEB-11), SSC 2019-2025.
insert into public.board_results (exam, year, examinees, passed, gpa5) values
  ('ssc', 2019, 112, 98, 21),
  ('ssc', 2020, 118, 109, 30),
  ('ssc', 2021, 121, 117, 44),
  ('ssc', 2022, 125, 116, 38),
  ('ssc', 2023, 130, 119, 35),
  ('ssc', 2024, 128, 121, 41),
  ('ssc', 2025, 134, 129, 47);

